const LEX_CLASSES={n:'Substantiv',vblex:'Verb',adj:'Adjektiv',adv:'Adverb',prn:'Pronomen',det:'Determinativ / talord',pr:'Preposisjon',cnjsub:'Subjunksjon',cnjcoo:'Konjunksjon',cnjadv:'Bindeord',ij:'Interjeksjon',part:'Infinitivsmerke',np:'Eigennamn',other:'Andre'};
const LexiconSearch={
 normalize:s=>s.normalize('NFC').toLocaleLowerCase('nb').trim().replace(/\s+/g,' '),
 search(rows,{query='',direction='bm',pos='',different=false,mode='prefix'}={}){
  const q=this.normalize(query),idx=direction==='bm'?0:1,mask=direction==='bm'?2:1;
  let found=[];
  for(const row of rows){if(!(row[3]&mask)||(pos&&row[2]!==pos)||(different&&this.normalize(row[0])===this.normalize(row[1])))continue;
   const word=this.normalize(row[idx]);if(q&&(mode==='exact'?word!==q:mode==='contains'?!word.includes(q):!word.startsWith(q)))continue;
   found.push({row,rank:word===q?0:word.startsWith(q)?1:2});
  }
  const collator=new Intl.Collator('nb',{sensitivity:'base',numeric:true});
  found.sort((a,b)=>a.rank-b.rank||collator.compare(a.row[idx],b.row[idx])||collator.compare(a.row[1-idx],b.row[1-idx])||a.row[2].localeCompare(b.row[2]));return found.map(x=>x.row);
 }
};
const lexiconCache={};let pairViewId=0;
async function loadLexicon(kind){if(!lexiconCache[kind])lexiconCache[kind]=fetch(`lexicon/${kind}.json`).then(r=>{if(!r.ok)throw Error();return r.json()}).catch(e=>{delete lexiconCache[kind];throw e});return lexiconCache[kind]}
const lexCredit=()=>`<p class="attribution">Ordpar frå <a href="https://github.com/apertium/apertium-nno-nob" target="_blank" rel="noopener">Apertium og bidragsytarane deira</a> · GPL v2 eller seinare · Tilpassa av Nynorsklab.</p><details class="lex-source"><summary>Kjelder, dekning og nedlasting</summary><div><p>Ordgrunnlaget kjem frå <a href="https://github.com/apertium/apertium-nno-nob" target="_blank" rel="noopener">Apertium</a> (20.10.2026). ${LEX_META.words.toLocaleString('nb')} oppføringar for ord og uttrykk, og ${LEX_META.names.toLocaleString('nb')} for namn. Ei oppføring er eit ordpar med ordklasse; same ord kan ha fleire tydingar eller klassar.</p><p>Dette er grunnformer frå ei omsetjingsordbok. Retningsavgrensingar er bevarte. Maskinomsetjingsreglar, kontekstval og automatisk bøying er ikkje køyrde. Namn, samansetningar, fagord og talord er med. Nokre tekniske oppføringar er utelatne. Lista er omfattande, men dekkjer ikkje alle norske ord eller tydingar. Kontroller gjeldande skrivemåte i Ordbøkene.</p><p>Copyright © 2009–2024 Apertium contributors. Takk til Kevin Brubeck Unhammer, Trond Trosterud og alle dei andre som er namngjevne i bidragsytarlista. Data og konvertering er delte under GNU GPL v2 eller seinare, utan garanti. Kjeldefila er uendra; oppføringane er utvida, filtrerte og sorterte til JSON av Nynorsklab 20.10.2026.</p><div class="button-row"><a class="textlink" href="lexicon/source.zip" download>Kjeldedata + konverteringsskript ↓</a><a class="textlink" href="lexicon/COPYING.txt" target="_blank">Lisens ↗</a><a class="textlink" href="lexicon/AUTHORS.txt" target="_blank">Bidragsytarar ↗</a><a class="textlink" href="lexicon/ACKNOWLEDGEMENTS.txt" target="_blank">Takkseiingar ↗</a><a class="textlink" href="https://github.com/Hrafnir/nynorsklab/blob/main/CREDITS.md" target="_blank" rel="noopener">Kjelder og kreditering ↗</a><a class="textlink" href="lexicon/meta.json" target="_blank">Datagrunnlag ↗</a></div></div></details>`;
function renderPairSearch(container){const view=++pairViewId;let query='',pos='',different=false,mode='prefix',kind='words',page=0,rows=[],found=[],busy=false,loadId=0;const pageSize=30;
 container.innerHTML=`<section class="panel"><div class="section-head"><div><div class="eyebrow">EIT STØRRE ORDROM</div><h2>Bokmål møter nynorsk.</h2></div><span class="pill">${LEX_META.words.toLocaleString('nb')} ordoppføringar</span></div><p class="small">Finn grunnformer, uttrykk og alternative ordval. Eit forslag må alltid passe til det du meiner.</p><form id="pair-form"><label for="pair-search">Søk i ordparlista</label><div class="searchform"><input id="pair-search" placeholder="Til dømes mulighet, bærekraft eller undersøking …" maxlength="100" autocomplete="off"><button class="button" type="submit">Finn ord →</button><button id="swap" type="button" class="button secondary">${direction==='bm'?'Bokmål → nynorsk':'Nynorsk → bokmål'} ⇄</button></div><div class="lex-filters"><div><label for="pair-class">Ordklasse</label><select id="pair-class"><option value="">Alle ordklassar</option>${Object.entries(LEX_CLASSES).filter(([k])=>k!=='np'&&k!=='other').map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div><label for="pair-match">Søkemåte</label><select id="pair-match"><option value="prefix">Heile ord og starten av ord</option><option value="exact">Berre heile ordet</option><option value="contains">Inneheld søket</option></select></div><div><label for="pair-kind">Ordgrunnlag</label><select id="pair-kind"><option value="words">Ord og uttrykk</option><option value="names">Eigennamn</option><option value="school">Skuleord med forklaring</option></select></div></div><label class="inline-check"><input id="pair-different" type="checkbox"> Vis berre ulik skrivemåte</label></form><div id="pair-info" class="small muted" role="status"></div><div id="pair-curated"></div><div id="pair-results"></div><div id="pair-pager" class="section-head" style="margin-top:20px"></div><div id="pair-lemma"></div></section>${lexCredit()}`;
 const alive=()=>view===pairViewId&&container.isConnected&&container.querySelector('#pair-search');
 const sourceRows=()=>PAIRS.map(x=>[x.bm,x.nn,'other',3,x.note]);
 const official=(w,dict)=>{dictMode('official');$('#word').value=w;$('#dict').value=dict;lookup()};
 function attachLookups() {container.querySelectorAll('[data-lexlookup]').forEach(b=>b.onclick=()=>official(b.dataset.lexlookup,b.dataset.dict));container.querySelectorAll('[data-lexsave]').forEach(b=>b.onclick=()=>{const word=b.dataset.lexsave;let saved=read('words',[]);if(!saved.some(x=>x.word===word&&x.dict==='nn'))saved.push({word,dict:'nn'});if(save('words',saved)){b.textContent='✓ Lagra';$('#saved-tab').textContent=`Mine ord (${saved.length})`}else toast('Kunne ikkje lagre ordet i nettlesaren.')})}
 function draw(){if(!alive())return;const idx=direction==='bm'?0:1,other=1-idx,totalPages=Math.max(1,Math.ceil(found.length/pageSize));page=Math.min(page,totalPages-1);
  $('#pair-info').textContent=busy?'Lastar ordgrunnlaget …':`${found.length.toLocaleString('nb')} treff${query?` på «${query}»`:''} · ${direction==='bm'?'bokmål → nynorsk':'nynorsk → bokmål'} · side ${page+1} av ${totalPages}`;
  const curated=kind==='words'&&query?PAIRS.filter(x=>LexiconSearch.normalize(x[direction])===LexiconSearch.normalize(query)):[];
  $('#pair-curated').innerHTML=curated.length?`<div class="tip" style="margin-top:15px"><strong>Skuleord · forklart i samanheng</strong>${curated.map(p=>`<p><b>${esc(p.bm)} ⇄ ${esc(p.nn)}</b> <span class="small">${esc(p.note)}</span></p>`).join('')}</div>`:'';
  $('#pair-results').innerHTML=busy?'<div class="loading">Ordlista blir henta éin gong og søkt i på eininga di.</div>':found.length?`<div class="lex-table-head"><span>${direction==='bm'?'BOKMÅL':'NYNORSK'}</span><span>${direction==='bm'?'NYNORSK':'BOKMÅL'}</span><span>UNDERSØK VIDARE</span></div>${found.slice(page*pageSize,(page+1)*pageSize).map(r=>`<article class="lex-row"><div><strong>${esc(r[idx])}</strong><small>${esc(LEX_CLASSES[r[2]]||r[2])}</small></div><div><strong>${esc(r[other])}</strong><small>${r[4]?esc(r[4]):r[3]===3?'Ordval avheng av tydinga':'Retningsavgrensa forslag · vurder konteksten'}</small></div><div class="lex-actions"><button class="plain" data-lexlookup="${esc(r[1])}" data-dict="nn">Nynorskordboka ↗</button><button class="plain" data-lexlookup="${esc(r[0])}" data-dict="bm">Bokmålsordboka ↗</button><button class="plain" data-lexsave="${esc(r[1])}">＋ Lagre nynorskord</button></div></article>`).join('')}`:`<div class="empty"><h3>Ingen treff med desse vala.</h3><p>Prøv grunnforma, ein annan ordklasse eller søkemåten «Inneheld søket». At eit ord manglar her, betyr ikkje at det er feil.</p><button class="button secondary" id="find-lemma">Finn grunnforma i Ordbøkene ↗</button></div>`;
  $('#pair-pager').innerHTML=busy?'':`<button class="button secondary" id="pair-prev" ${page===0?'disabled':''}>← Førre</button><span class="small">${found.length?`${page*pageSize+1}–${Math.min((page+1)*pageSize,found.length)} av ${found.length.toLocaleString('nb')}`:'0 treff'}</span><button class="button secondary" id="pair-next" ${page+1>=totalPages?'disabled':''}>Neste →</button>`;
  if($('#pair-prev'))$('#pair-prev').onclick=()=>{page--;draw()};if($('#pair-next'))$('#pair-next').onclick=()=>{page++;draw()};
  if($('#find-lemma'))$('#find-lemma').onclick=findLemma;attachLookups();
 }
 function search(){if(!alive()||busy)return;query=$('#pair-search').value.trim();found=LexiconSearch.search(rows,{query,direction,pos,different,mode});page=0;$('#pair-lemma').innerHTML='';draw()}
 async function load(){const ticket=++loadId,requestedKind=kind;busy=true;draw();try{const loaded=requestedKind==='school'?sourceRows():await loadLexicon(requestedKind);if(!alive()||ticket!==loadId)return;rows=loaded;busy=false;search()}catch{if(!alive()||ticket!==loadId)return;busy=false;$('#pair-info').textContent='Ordgrunnlaget kunne ikkje lastast.';$('#pair-results').innerHTML='<p>Prøv på nytt, eller vel skuleordlista som ligg i appen.</p><button class="button secondary" id="lex-retry">Prøv igjen</button>';$('#lex-retry').onclick=load}}
 async function findLemma(){query=$('#pair-search').value.trim();if(!query)return;const ticket=query,dict=direction;$('#pair-lemma').innerHTML='<p class="small">Leitar etter grunnformer i Ordbøkene …</p>';try{const data=await api(`https://ord.uib.no/api/suggest?q=${encodeURIComponent(query)}&dict=${dict}&include=i&n=12`);if(!alive()||query!==ticket||direction!==dict)return;const suggestions=[...new Set((data.a?.inflect||[]).map(x=>x[0]))];$('#pair-lemma').innerHTML=suggestions.length?`<p class="small">Prøv ei av desse grunnformene:</p><div class="button-row">${suggestions.map(x=>`<button class="button secondary lemma-choice" data-lemma="${esc(x)}">${esc(x)}</button>`).join('')}</div>`:'<p class="small">Fann inga grunnform. Prøv oppslag direkte i Ordbøkene.</p>';container.querySelectorAll('.lemma-choice').forEach(b=>b.onclick=()=>{$('#pair-search').value=b.dataset.lemma;search()})}catch{if(alive())$('#pair-lemma').textContent='Ordbøkene svarar ikkje no. Prøv igjen seinare.'}}
 let timer;$('#pair-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(search,180)};$('#pair-form').onsubmit=e=>{e.preventDefault();clearTimeout(timer);search()};$('#pair-class').onchange=e=>{pos=e.target.value;search()};$('#pair-match').onchange=e=>{mode=e.target.value;search()};$('#pair-different').onchange=e=>{different=e.target.checked;search()};$('#pair-kind').onchange=e=>{kind=e.target.value;pos='';$('#pair-class').value='';$('#pair-class').disabled=kind!=='words';load()};$('#swap').onclick=()=>{direction=direction==='bm'?'nn':'bm';$('#swap').textContent=(direction==='bm'?'Bokmål → nynorsk':'Nynorsk → bokmål')+' ⇄';search()};load();
}
